import {RARE_MAKO,discoveryGrowth} from './wayglass-model.js?v=5.11.0';
import {resonanceSources} from './resonance-link.js';
import {CREW} from './mako.js?v=5.16.0';
import {PATHS,nodesFor,ownedNodes,availablePoints,earnedPoints,nodeState,unlockNode} from './skill-grid-model.js?v=5.16.0';
const el=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;};
export function skillGrid({world,data,onSave,onBack,inBattle=false,initialMakoId=null,onCraft=null,initialHero=null,initialNodeId=null}){const s=world.state,root=el('section','sphere-grid');let hero=s.recruited.includes(initialHero)?initialHero:s.party[0],selected=initialNodeId||(initialMakoId?'mako:'+initialMakoId:'origin'),zoom=.65,branch=(initialMakoId||initialNodeId)?(nodesFor(hero).find(v=>v.id===selected)?.branch??-1):-1;const head=el('div','grid-toolbar'),crew=el('div','crew-tabs');for(const id of s.recruited){const b=el('button','',CREW[id].name);b.onclick=()=>{hero=id;selected='origin';paint();};b.dataset.hero=id;crew.append(b);}head.append(crew);const points=el('p','grid-points');head.append(points);root.append(head);const story=el('div','resonance-banner');story.append(el('span','resonance-emblem','◈'),el('div',''));story.lastChild.append(el('small','eyebrow','CLAY REMEMBERS • YOU CHOOSE ITS SHAPE'),el('p','','Mako cores hold patterns carried by clay and water. These paths turn what you learn into strength, technique and control. Rook’s portable Wayglass follows mineral seams; it records no captive voices. Find a crystal, learn its attunement here, then fit it in Crystal craft.'));root.append(story);const collected=el('details','resonance-ledger'),summary=el('summary','','Attunements · crystals & discoveries');collected.append(summary);const crystalList=el('div','crystal-ledger');for(const core of ['earth','mend','flame','ward','tide','gale','shade','frost','volt','gravity']){const chip=el('span',s.cores.includes(core)?'crystal-chip discovered':'crystal-chip dormant',s.cores.includes(core)?core:'Undiscovered');crystalList.append(chip);}collected.append(el('p','', 'Find cores in the world, equip them in Crystal craft, then develop their mastery here. Recovering rare Mako grants discovery growth. Recovered environmental caches also grant their travelling companions growth and affinity AP. Calibration only locates the seam; it does not grant the crystal or teach its attunement.'),crystalList);const sources=resonanceSources(s);for(const r of sources)collected.append(el('p','resonance-source',r.label+' · +'+r.points+' growth'));if(!sources.length)collected.append(el('p','muted','No crystal discoveries yet. Pack Rook’s Wayglass beside his reader after learning your first core.'));root.append(collected);const filters=el('div','grid-filters');for(const [i,name]of [[-1,'All paths'],...PATHS.map((v,i)=>[i,v.name])]){const b=el('button','',name);b.onclick=()=>{branch=i;paint();};b.dataset.branch=i;filters.append(b);}root.append(filters);const layout=el('div','grid-layout'),viewport=el('div','grid-viewport');viewport.setAttribute('aria-label','Skill board. Scroll or swipe to explore.');viewport.tabIndex=0;const stage=el('div','grid-stage');viewport.append(stage);const info=el('aside','grid-detail');info.setAttribute('aria-live','polite');layout.append(viewport,info);root.append(layout);const controls=el('div','grid-controls');function scale(z,center=false){const cx=(viewport.scrollLeft+viewport.clientWidth/2)/zoom,cy=(viewport.scrollTop+viewport.clientHeight/2)/zoom;zoom=Math.max(.35,Math.min(1.5,z));stage.style.width=1600*zoom+'px';stage.style.height=1600*zoom+'px';const board=stage.firstChild;if(board)board.style.transform='scale('+zoom+')';viewport.scrollLeft=(center?800:cx)*zoom-viewport.clientWidth/2;viewport.scrollTop=(center?800:cy)*zoom-viewport.clientHeight/2;}
for(const [label,fn]of [['− Zoom out',()=>scale(zoom-.15)],['+ Zoom in',()=>scale(zoom+.15)],['Center',()=>scale(zoom,true)],['Back to pause',onBack]]){const b=el('button','',label);b.onclick=fn;controls.append(b);}root.append(controls,el('p','grid-help','Swipe or scroll to explore · Select a node to inspect · Follow illuminated paths from the center. Level up for 2 points · Every two story victories: +1 · Recover rare Mako with the Wayglass for discovery growth and unique attunement nodes.'));
function describe(n){if(n.stat==='mako'){const r=RARE_MAKO.find(r=>r.id===n.makoId);return r.effect+' Find it with Rook’s Wayglass in '+r.place+'. Activate Crystal mastery '+(r.stage-1)+', then this node. Equip it on this character in Crystal craft.';}if(n.id==='origin')return 'The beginning of '+CREW[hero].name+'’s path. Choose a connected node to shape their growth.';if(n.stat==='skill')return 'Learn '+data.skills.characters[hero].skills[n.step].name+'. Available from the Personal command in battle.';if(n.stat==='ap')return 'Gain 18 '+CREW[hero].affinity+' AP. Crystal ranks increase at 35 and 120 AP; equip this core in Crystal craft.';return 'Shape the pattern into a permanent gain of '+(n.stat==='speed'?'2.5% base speed':n.value+' '+PATHS[n.branch].name.toLowerCase())+'.';}
function detail(n){info.replaceChildren();const state=nodeState(s,hero,n),path=PATHS[n.branch];info.append(el('small','eyebrow',path?.name||'THE ORIGIN'),el('div','grid-sigil',path?.icon||'✺'),el('h3','',n.stat==='skill'?data.skills.characters[hero].skills[n.step].name:n.name),el('p','',describe(n)));const labels={undiscovered:'Find this crystal with the Wayglass first',pattern:'Learn its base core through the story first',learned:'Activated',locked:'Follow the previous node first',story:'Reach chapter 2 to awaken this path',unaffordable:'Earn more growth points',available:'Ready to activate'};info.append(el('p','node-status '+state,labels[state]));if(n.cost)info.append(el('p','muted','Cost: '+n.cost+' growth point'+(n.cost>1?'s':'')+' · Available: '+availablePoints(s,hero)));const unlock=el('button','primary',inBattle?'Progression is paused during battle':state==='learned'?'Already activated':'Activate node');unlock.disabled=inBattle||state!=='available';unlock.onclick=()=>{if(unlockNode(s,hero,n.id)){onSave();if(initialMakoId){const target=nodesFor(hero).find(v=>v.id==='mako:'+initialMakoId);if(target?.requires===n.id){selected=target.id;branch=target.branch;}}paint();}};info.append(unlock);if(n.stat==='mako'&&state==='learned'&&onCraft){const equip=el('button','primary','Fit '+RARE_MAKO.find(r=>r.id===n.makoId).name+' in Crystal craft');equip.onclick=()=>onCraft(n.makoId,hero);info.append(equip);}if(n.requires&&n.requires!=='origin'){const prev=el('button','',n.stat==='mako'?'Find '+(nodesFor(hero).find(v=>v.id===n.requires)?.name||'prerequisite'):'Find prerequisite');prev.onclick=()=>{selected=n.requires;branch=nodesFor(hero).find(v=>v.id===selected)?.branch??-1;paint();const p=nodesFor(hero).find(v=>v.id===selected);viewport.scrollLeft=p.x*zoom-viewport.clientWidth/2;viewport.scrollTop=p.y*zoom-viewport.clientHeight/2;};info.append(prev);} }
function paint(){const oldX=viewport.scrollLeft,oldY=viewport.scrollTop;stage.replaceChildren();for(const b of crew.children)b.setAttribute('aria-pressed',String(Number(b.dataset.hero)===hero));for(const b of filters.children)b.setAttribute('aria-pressed',String(Number(b.dataset.branch)===branch));const own=ownedNodes(s,hero),nodes=nodesFor(hero).filter(n=>!n.doctrine);points.textContent=availablePoints(s,hero)+' growth points · '+(own.size-1)+'/'+(nodesFor(hero).length-1)+' activated · '+earnedPoints(s,hero)+' earned';const board=el('div','grid-board');stage.append(board);const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 1600 1600');svg.classList.add('grid-links');board.append(svg);for(const r of [115,279,443,607,735]){const ring=document.createElementNS(svg.namespaceURI,'circle');for(const [k,v]of Object.entries({cx:800,cy:800,r,fill:'none',stroke:'#92cbd52c','stroke-width':1,'stroke-dasharray':r===735?'2 12':'4 7'}))ring.setAttribute(k,v);svg.append(ring);}for(let a=0;a<56;a++){const angle=a*Math.PI/28,line=document.createElementNS(svg.namespaceURI,'line');for(const [k,v]of Object.entries({x1:800+Math.cos(angle)*720,y1:800+Math.sin(angle)*720,x2:800+Math.cos(angle)*(a%8===0?745:730),y2:800+Math.sin(angle)*(a%8===0?745:730),stroke:'#b0d9df66','stroke-width':2}))line.setAttribute(k,v);svg.append(line);} for(const n of nodes){if(n.requires){const p=nodes.find(v=>v.id===n.requires),line=document.createElementNS(svg.namespaceURI,'line');for(const [k,v]of Object.entries({x1:p.x,y1:p.y,x2:n.x,y2:n.y,stroke:PATHS[n.branch].color}))line.setAttribute(k,v);line.classList.add(own.has(n.id)?'lit':'dim');if(branch>=0&&n.branch!==branch)line.style.opacity='.08';svg.append(line);}const state=nodeState(s,hero,n),b=el('button','sphere-node '+state+(selected===n.id?' inspected':''),PATHS[n.branch]?.icon||'✺');const gem=document.createElementNS(svg.namespaceURI,'svg');gem.setAttribute('viewBox','0 0 60 60');gem.setAttribute('aria-hidden','true');gem.classList.add('node-gem');const facets=[['M30 3 52 20 46 44 30 57 14 44 8 20Z','#ffffff18'],['M30 3 30 30 8 20Z','#ffffff55'],['M30 3 52 20 30 30Z','#ffffff2a'],['M8 20 30 30 14 44Z','#ffffff15'],['M52 20 46 44 30 30Z','#00000044'],['M14 44 30 30 30 57Z','#ffffff33'],['M30 30 46 44 30 57Z','#00000033']];for(const [d,fill]of facets){const f=document.createElementNS(svg.namespaceURI,'path');f.setAttribute('d',d);f.setAttribute('fill',fill);gem.append(f);}b.prepend(gem);const glyph=el('span','node-glyph',b.lastChild.textContent);b.lastChild.remove();b.append(glyph);b.style.left=n.x+'px';b.style.top=n.y+'px';b.style.setProperty('--node',PATHS[n.branch]?.color||'#e9d4a0');b.setAttribute('aria-label',n.name+' · '+state+(n.cost?' · '+n.cost+' points':''));b.setAttribute('aria-pressed',String(n.id===selected));if(n.stat==='mako')b.dataset.mako=n.makoId;if(branch>=0&&n.branch>=0&&n.branch!==branch)b.classList.add('faded');b.onclick=()=>{selected=n.id;paint();};b.onfocus=()=>detail(n);board.append(b);if(n.step===7||n.stat==='mako'){const label=el('span','path-label',n.stat==='mako'?RARE_MAKO.find(r=>r.id===n.makoId).name:PATHS[n.branch].name);label.style.left=n.x+'px';label.style.top=n.y+45+'px';board.append(label);}}scale(zoom);viewport.scrollLeft=oldX;viewport.scrollTop=oldY;detail(nodes.find(n=>n.id===selected)||nodes[0]);}
paint();requestAnimationFrame(()=>{scale(zoom,true);if(initialMakoId||initialNodeId){const n=nodesFor(hero).find(v=>v.id===selected);if(n){viewport.scrollLeft=n.x*zoom-viewport.clientWidth/2;viewport.scrollTop=n.y*zoom-viewport.clientHeight/2;}}});return root;}
